    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da LSI: as famílias são selecionadas pelos Accommodation Officers da própria escola e visitadas com regularidade. Você pode escolher quarto individual (ou twin, quando duas pessoas reservam para o mesmo período) com café da manhã ou meia pensão. Roupa de cama e toalhas são fornecidas e trocadas semanalmente e o anfitrião oferece pelo menos uma lavagem de roupa por semana sem custo. Quem reserva só com café da manhã normalmente não tem acesso à cozinha. Há a opção Executive, com banheiro privativo (ensuite ou de uso exclusivo), mediante suplemento. Em Auckland, o quarto sempre tem cama, cadeira, mesa ou escrivaninha, luminária, espelho, aquecedor e cômoda ou guarda-roupa. O anfitrião fornece roupa de cama, toalhas e lava a sua roupa uma vez por semana (itens de higiene pessoal não estão inclusos). As refeições contratadas são preparadas pela família e, em geral, a cozinha não fica disponível para o aluno cozinhar. Nesta opção você fica em quarto individual com banheiro privativo, de uso exclusivo. O regime é de meia pensão, com café da manhã e jantar inclusos; o almoço fica por sua conta.</p><p>Suplementos e condições: Suplemento dieta especial: NZD 80/semana; Outro suplemento: NZD 90.</p><p>O preço semanal desta linha já é a tarifa Executive (quarto com banheiro privativo): tarifa base mais o suplemento de NZ$90 por semana, que portanto não deve ser somado novamente. Suplementos da casa de família em LSI Auckland, por pessoa por semana: aquecimento de inverno NZ$10 de 1/jun a 31/ago; Natal (26-27/dez e 2-3/jan) NZ$90; dieta especial NZ$40 com café da manhã e NZ$80 com meia pensão; quarto executivo com banheiro privativo NZ$90. Taxa de colocação da acomodação NZ$330. Taxa de inscrição da escola NZ$230, courier NZ$145, transfer do aeroporto NZ$145 somente ida. Taxa não reembolsável de NZ$100 de mudança/kit de chegada. Chegadas e saídas de sábado a sábado ou de domingo a domingo. Os preços podem mudar ao longo do ano; confirme com a LSI Auckland na reserva. Fonte: LSI Prices and Dates 2026.</p>','["Famílias Selecionadas e Visitadas pela Escola", "Roupa de Cama e Toalhas Trocadas Semanalmente", "1 Lavagem de Roupa por Semana Inclusa", "Quarto Individual ou Twin", "Imersão Cultural", "Prática Diária de Inglês", "Opção Executive com Banheiro Privativo", "Chegadas aos Sábados ou Domingos", "Quarto Individual", "Banheiro Privativo", "Meia Pensão", "Ideal para quem quer imersão cultural e prática diária de inglês", "Ideal para quem prefere ter refeições resolvidas em casa", "Ideal para quem viaja sozinho e quer apoio de anfitriões locais", "Ideal para quem busca bom custo-benefício com serviços inclusos", "Ideal para quem valoriza privacidade total e silêncio para estudar", "Ideal para quem prefere não dividir banheiro com ninguém", "Ideal para quem quer café da manhã e jantar garantidos e economia no dia a dia"]'::jsonb,'["Menos indicado para quem quer cozinhar livremente (sobretudo no regime só com café da manhã)", "Menos indicado para quem precisa morar a poucos minutos da escola", "Menos indicado para quem quer liberdade total de horários e visitas", "Menos indicado para quem prefere a vida social de uma residência estudantil", "Menos indicado para quem procura a alternativa mais barata", "Menos indicado para quem quer dividir o quarto com um amigo para reduzir custos", "Menos indicado para quem tem horários irregulares e prefere jantar fora com frequência"]'::jsonb);
